import{respFigure,respSVG,rt}from './resp-figures.js?v=20261023-physicscomplete01';
const phase=(p,n)=>Math.min(n-1,Math.floor(Math.max(0,Math.min(1,p))*n));
const make=(title,steps,note,render)=>({title,steps,note,render,duration:12});
export const respFilms={
 'resp-aerobic':make('Aerobic respiration: inputs to energy use',['Glucose and oxygen supply the material reactants.','Aerobic respiration takes place in living cells.','Carbon dioxide and water are products.','Transferred energy supports synthesis, movement and warmth.'],'Overall summary, not biochemical steps or ATP counts. Stages do not represent biological durations; breathing and cellular respiration are different.',p=>{let n=phase(p,4),x=60+p*440;return respSVG('<ellipse cx="280" cy="180" rx="110" ry="75" fill="#b99b82" stroke="#e1c7a7" stroke-width="4"/>'+rt(280,185,'Living cell',23)+`<circle cx="${x}" cy="275" r="10" fill="#edab94"/>`+rt(280,60,n<2?'Glucose + oxygen':'Carbon dioxide + water',24)+rt(280,350,n===3?'Energy for living processes':'Exothermic respiration',23),'Overall aerobic respiration process; symbolic matter and energy routes.');}),
 'resp-anaerobic':make('Anaerobic routes: organism matters',['Glucose can transfer energy without oxygen.','In muscle cells, lactic acid is produced.','In plant/yeast cells, ethanol and carbon dioxide are produced.','Yeast fermentation supplies CO₂ for bread and ethanol for drinks.'],'Separate worked examples, not one cell changing organism. Much less energy per glucose than aerobically; times and particle sizes symbolic.',p=>respFigure({kind:'fermentation',state:['muscle','muscle','yeast','bread'][phase(p,4)],result:'No oxygen used; incomplete oxidation transfers less energy.'})),
 'resp-exercise':make('Exercise: demand and oxygen delivery',['Working muscles need more energy.','Breathing rate and breath volume increase.','Heart rate increases, helping deliver oxygenated blood.','Muscle aerobic respiration uses oxygen; insufficient supply brings anaerobic contribution.'],'Linked responses occur together, not as four isolated switches. This is a route summary, not a personal fitness or recovery forecast.',p=>{let nodes=['Muscle demand','Ventilation','Circulation','Muscle supply'],n=phase(p,4);return respSVG(nodes.map((x,i)=>`<rect x="${30+i*130}" y="140" width="110" height="80" rx="20" fill="${n===i?'#bd967b':'#35536a'}"/>`+rt(85+i*130,185,x,13)).join('')+rt(280,70,'Supply oxygen for greater energy transfer',23)+rt(280,330,'Responses overlap in the living body',21),'Four highlighted components connect muscle demand to oxygen delivery.');}),
 'resp-recovery':make('Recovery: muscle to liver',['Lactic acid accumulates in working muscle.','Blood transports lactic acid away from muscle.','The liver processes the transported lactic acid.','Lactic acid is converted back into glucose in this specification account.'],'Higher-only simplified route. Extra post-exercise oxygen is the oxygen-debt requirement; the film is not a complete biochemical pathway or clock for recovery.',p=>respFigure({kind:'recovery',step:phase(p,4),result:'Extra oxygen after exercise is above the resting requirement.'})),
 'resp-metabolism':make('Metabolic synthesis: build one lipid',['One glycerol molecule supplies one kind of building block.','Fatty acids supply the other kind of building block.','Three fatty acids are needed for each glycerol in this model.','Enzyme-controlled synthesis forms lipid; respiration supplies energy.'],'One selected synthesis route in metabolism. Bars denote building blocks, not molecular geometry. Other metabolic routes include carbohydrate/protein synthesis and breakdown, respiration and urea formation.',p=>respFigure({kind:'lipid',glycerol:1,fatty:[0,1,3,3][phase(p,4)],result:'One glycerol + three fatty acids → lipid; energy supports synthesis.'}))
};
